{
  "groups": [
    {
      "group_id": "E1",
      "queries": [
        "2025年员工离职率披露，包括总离职率、主动离职率及统计口径说明 (Employee turnover rate disclosure for 2025, including total and voluntary turnover rates with methodology)",
        "评分期间员工流失数据及离职率计算依据 (Employee attrition data and turnover rate calculation basis during the scoring period)"
      ]
    },
    {
      "group_id": "E2",
      "queries": [
        "劳动合同签订率、续签政策及合同期限管理 (Labor contract signing rate, renewal policies, and contract term management)",
        "依法与员工签订劳动合同的具体安排及权利义务保障 (Specific arrangements for signing labor contracts in accordance with law and protection of rights and obligations)"
      ]
    },
    {
      "group_id": "E3",
      "queries": [
        "裁员通知、协商程序、经济补偿标准及辞退福利支付 (Layoff notification, consultation procedures, economic compensation standards, and severance pay)",
        "解除劳动关系争议处理机制及离职补偿事实 (Dispute resolution mechanisms for termination of labor relations and facts regarding separation compensation)"
      ]
    },
    {
      "group_id": "E4",
      "queries": [
        "内部招聘、竞聘转岗制度及岗位轮换实施情况 (Internal recruitment, competitive hiring, transfer systems, and job rotation implementation)",
        "再就业服务、职业转换培训及退休返聘支持措施 (Re-employment services, career transition training, and retirement re-hiring support measures)"
      ]
    },
    {
      "group_id": "E5",
      "queries": [
        "2025年度实际发生的终止补偿支付记录及离职安置受益结果 (Actual termination compensation payment records and separation placement benefit results incurred in 2025)",
        "当期已完成的离职保障纠正措施及有效执行证据 (Completed separation guarantee corrective measures and evidence of effective execution in the current period)"
      ]
    },
    {
      "group_id": "P1",
      "queries": [
        "工资按时足额支付保障政策及最低工资合规执行 (Guarantee policies for timely and full wage payment and minimum wage compliance execution)",
        "具体工资支付周期安排及法定支付义务履行事实 (Specific wage payment cycle arrangements and fulfillment of statutory payment obligations)"
      ]
    },
    {
      "group_id": "P2",
      "queries": [
        "工资核算复核机制、工资单发放及差错查询途径 (Wage calculation review mechanism, payslip distribution, and error inquiry channels)",
        "薪酬申诉渠道及工资支付问题处理安排 (Compensation appeal channels and handling arrangements for wage payment issues)"
      ]
    },
    {
      "group_id": "P3",
      "queries": [
        "工资支付定期检查、监测制度或内部审计范围 (Regular checks, monitoring systems, or internal audit scope for wage payments)",
        "人力资源审计或人权尽调中涉及工资支付的核查事实 (Verification facts involving wage payments in HR audits or human rights due diligence)"
      ]
    },
    {
      "group_id": "P4",
      "queries": [
        "工资支付保障政策的适用对象及覆盖范围说明 (Applicable subjects and coverage scope of wage payment guarantee policies)",
        "特定地区、子公司或员工类别的工资保障覆盖人数或比例 (Number or proportion of employees covered by wage guarantees in specific regions, subsidiaries, or categories)"
      ]
    },
    {
      "group_id": "P5",
      "queries": [
        "欠薪补发、错误扣款退还及加班费支付问题的补救机制 (Remedial mechanisms for back-pay, refund of erroneous deductions, and overtime payment issues)",
        "已完成工资差错纠正事实及支付争议复核结果 (Facts of completed wage error corrections and review results of payment disputes)"
      ]
    },
    {
      "group_id": "T1",
      "queries": [
        "员工工作时间、排班轮班制度及合理工时控制政策 (Employee working hours, shift scheduling systems, and reasonable working time control policies)",
        "每周工作天数、每日工时上限及特定岗位工时安排 (Weekly working days, daily hour limits, and working time arrangements for specific positions)"
      ]
    },
    {
      "group_id": "T2",
      "queries": [
        "加班申请审批流程、自愿性原则及加班时长控制 (Overtime application approval process, voluntariness principle, and overtime duration control)",
        "加班异常处理安排及加班管理制度执行情况 (Arrangements for handling overtime anomalies and implementation of overtime management systems)"
      ]
    },
    {
      "group_id": "T3",
      "queries": [
        "员工休息权、法定节假日及带薪年假权利保障 (Protection of employee rest rights, statutory holidays, and paid annual leave entitlements)",
        "婚假、产假等具体休假安排及取得机制 (Specific leave arrangements such as marriage and maternity leave, and acquisition mechanisms)"
      ]
    },
    {
      "group_id": "T4",
      "queries": [
        "考勤系统应用、工时记录管理及排班检查机制 (Application of attendance systems, working time record management, and shift inspection mechanisms)",
        "员工休假申请流程及调休管理运行事实 (Employee leave application processes and operational facts of compensatory time off management)"
      ]
    },
    {
      "group_id": "T5",
      "queries": [
        "2025年度实际工时监测数据、带薪休假使用率及执行覆盖情况 (Actual working time monitoring data, paid leave usage rate, and execution coverage in 2025)",
        "当期已纠正的休息权侵害案例及工时休假执行结果 (Cases of corrected right-to-rest violations and working time/leave execution results in the current period)"
      ]
    },
    {
      "group_id": "W1",
      "queries": [
        "法定社会保险（养老、医疗、失业、工伤、生育）及住房公积金缴纳情况 (Payment status of statutory social insurance (pension, medical, unemployment, work injury, maternity) and housing provident fund)",
        "基本福利政策适用性及法定保障合规事实 (Applicability of basic welfare policies and compliance facts regarding statutory guarantees)"
      ]
    },
    {
      "group_id": "W2",
      "queries": [
        "补充医疗保险、商业保险、企业年金及餐交补助安排 (Arrangements for supplementary medical insurance, commercial insurance, enterprise annuities, and meal/transport subsidies)",
        "已为员工投保或发放补充福利的具体事实 (Specific facts of having insured employees or distributed supplementary benefits)"
      ]
    },
    {
      "group_id": "W3",
      "queries": [
        "育儿托育支持、家庭照护资源及员工援助计划(EAP) (Childcare and eldercare support, family care resources, and Employee Assistance Programs (EAP))",
        "心理咨询服务及面向员工的生活支持项目 (Psychological counseling services and life support programs for employees)"
      ]
    },
    {
      "group_id": "W4",
      "queries": [
        "福利适用对象界定、申请条件及领取报销规则 (Definition of welfare applicable subjects, application conditions, and receipt/reimbursement rules)",
        "补贴标准及福利获取的具体操作流程 (Subsidy standards and specific operational procedures for obtaining benefits)"
      ]
    },
    {
      "group_id": "W5",
      "queries": [
        "2025年度实际参保、投保、缴纳及补贴发放记录 (Records of actual insurance enrollment, premium payment, contributions, and subsidy disbursements in 2025)",
        "员工已使用福利服务或具体受益案例证明 (Proof of employees having used welfare services or specific beneficiary cases)"
      ]
    },
    {
      "group_id": "D1",
      "queries": [
        "禁止就业歧视政策、反差别待遇制度及具体保障措施 (Policies prohibiting employment discrimination, anti-differential treatment systems, and specific safeguard measures)",
        "招聘、薪酬及晋升中的公平对待要求与执行事实 (Fair treatment requirements and enforcement facts in recruitment, compensation, and promotion)"
      ]
    },
    {
      "group_id": "D2",
      "queries": [
        "职场骚扰零容忍政策、反性骚扰规定及预防措施 (Zero-tolerance policies for workplace harassment, anti-sexual harassment regulations, and preventive measures)",
        "保护员工免受骚扰的具体制度或培训安排 (Specific systems or training arrangements to protect employees from harassment)"
      ]
    },
    {
      "group_id": "D3",
      "queries": [
        "歧视与骚扰投诉受理机构、调查程序及处理机制 (Acceptance bodies, investigation procedures, and handling mechanisms for discrimination and harassment complaints)",
        "当期针对歧视骚扰投诉的实际调查与处置事实 (Actual investigation and disposal facts regarding discrimination/harassment complaints in the current period)"
      ]
    },
    {
      "group_id": "D4",
      "queries": [
        "投诉人保密、匿名举报保护及不报复承诺 (Confidentiality for complainants, anonymous reporting protection, and non-retaliation commitments)",
        "受影响人员风险隔离与支持保护措施 (Risk isolation and supportive protective measures for affected individuals)"
      ]
    },
    {
      "group_id": "D5",
      "queries": [
        "查实歧视骚扰后的处分问责、移交处理及纠正补救机制 (Disciplinary accountability, referral handling, and corrective remedial mechanisms after verified discrimination/harassment)",
        "恢复机会、补偿不公及流程整改的实际处置事实 (Actual disposal facts regarding opportunity restoration, compensation for injustice, and process rectification)"
      ]
    }
  ]
}
